// Synthetic grammar projections frozen from Python3.11/Unicode14.
use localbrain_core::backend::search::{conditions, index, presentation};
use serde_json::Value;
#[test]
fn query_grammar_matches_frozen_legacy_scope_and_focus() {
    let all: Value = serde_json::from_str(CASES).unwrap();
    let now = chrono::DateTime::parse_from_rfc3339("2026-10-12T03:00:00+00:00")
        .unwrap()
        .with_timezone(&chrono::Utc);
    for case in all["queries"].as_array().unwrap() {
        let query = case["query"].as_str().unwrap();
        assert_eq!(
            serde_json::to_value(conditions::interpret(query, "Asia/Seoul", Some(now)).unwrap())
                .unwrap(),
            case["conditions"],
            "conditions {query:?}"
        );
        assert_eq!(
            conditions::focus_query(query),
            case["focus"],
            "focus {query:?}"
        );
        assert_eq!(
            serde_json::to_value(index::lexical_tokens(query)).unwrap(),
            case["tokens"],
            "tokens {query:?}"
        );
    }
    for case in all["returns"].as_array().unwrap() {
        let value = case["value"].as_str().unwrap();
        assert_eq!(
            presentation::safe_return(value),
            case["expected"],
            "return {value:?}"
        );
    }
}
